1	import {
2	  GOLD_GRANT_REASONS,
3	  grantAmount,
4	  itemPrice,
5	  SHOP_ITEMS,
6	  type GoldGrantReason,
7	  type ShopItem,
8	} from "@pirate-sea-race/content/objectives";
9	import {
10	  atTick,
11	  isPlayerId,
12	  playerRejection,
13	  tickRejection,
14	  updatePlayer,
15	  type LedgerRejection,
16	  type LedgerStep,
17	} from "./internal.js";
18	import {
19	  activeDuelOf,
20	  findPlayer,
21	  MAX_RECORDED_REFUSALS,
22	  type GoldGrant,
23	  type LedgerPlayer,
24	  type LedgerState,
25	  type PurchaseOutcome,
26	  type PurchaseRecord,
27	  type RecordedRefusal,
28	  type RefusalRecord,
29	} from "./state.js";
30	
31	function isKey(value: unknown): value is string {
32	  return typeof value === "string" && value.length > 0;
33	}
34	
35	function playerOf(state: LedgerState, playerId: unknown): LedgerPlayer | null {
36	  return typeof playerId === "string" ? (findPlayer(state, playerId) ?? null) : null;
37	}
38	
39	export interface GrantResult {
40	  readonly ok: boolean;
41	  readonly rejection: LedgerRejection | null;
42	  /** The grant made, or for a `duplicate` or `already-claimed` request the earlier grant that holds the key. */
43	  readonly grant: GoldGrant | null;
44	  /** The player as they now stand, or null for an unknown player. */
45	  readonly player: LedgerPlayer | null;
46	}
47	
48	export interface GrantGoldRequest {
49	  readonly playerId: string;
50	  readonly reason: GoldGrantReason;
51	  /** For `ruin`, the ruin's key `String(island)`; for `supply-cache`, one of the ledger's `supplyCaches`. */
52	  readonly sourceKey: string;
53	  readonly tick: number;
54	}
55	
56	/** Whether the ledger knows the grant's key: a ruin on one of its sources' islands, or one of its supply caches. */
57	export function knownGrantKey(state: LedgerState, reason: GoldGrantReason, sourceKey: string): boolean {
58	  if (reason === "supply-cache") return state.supplyCaches.includes(sourceKey);
59	  return state.sources.some((source) => String(source.island) === sourceKey);
60	}
61	
62	/** The earlier grant holding this request's key: the same player's for a ruin, anybody's for a supply cache. */
63	function grantHolding(state: LedgerState, reason: GoldGrantReason, sourceKey: string, playerId: string): GoldGrant | undefined {
64	  return state.grants.find(
65	    (grant) => grant.reason === reason && grant.sourceKey === sourceKey && (reason === "supply-cache" || grant.playerId === playerId),
66	  );
67	}
68	
69	/**
70	 * §11's minted gold: a fresh ruin completion (once per player per ruin) or a supply cache (one global claim). The
71	 * amount comes from the rules, and `goldIssued` grows by it. A key the ledger does not know is an `unknown-source`, so
72	 * no caller can mint by inventing keys. A repeat of the same player's key is a `duplicate`; a supply cache someone
73	 * else already claimed is `already-claimed`. A player who left gets nothing.
74	 */
75	export function grantGold(state: LedgerState, request: GrantGoldRequest): LedgerStep<GrantResult> {
76	  const { playerId, reason, sourceKey, tick } = request;
77	  const rejected = (rejection: LedgerRejection, grant: GoldGrant | null = null): LedgerStep<GrantResult> => ({
78	    state,
79	    result: { ok: false, rejection, grant, player: playerOf(state, playerId) },
80	  });
81	  const bad = tickRejection(state, tick);
82	  if (bad) return rejected(bad);
83	  if (!GOLD_GRANT_REASONS.includes(reason) || !isKey(sourceKey)) return rejected("invalid-request");
84	  if (!knownGrantKey(state, reason, sourceKey)) return rejected("unknown-source");
85	  const refusal = playerRejection(state, playerId);
86	  if (refusal) return rejected(refusal);
87	  const earlier = grantHolding(state, reason, sourceKey, playerId);
88	  if (earlier) return rejected(earlier.playerId === playerId ? "duplicate" : "already-claimed", earlier);
89	  const amount = grantAmount(state.rules, reason);
90	  const grant: GoldGrant = { reason, sourceKey, playerId, amount, tick };
91	  const next = updatePlayer(
92	    { ...atTick(state, tick), grants: [...state.grants, grant], goldIssued: state.goldIssued + amount },
93	    playerId,
94	    (player) => ({ ...player, gold: player.gold + amount }),
95	  );
96	  return { state: next, result: { ok: true, rejection: null, grant, player: findPlayer(next, playerId) ?? null } };
97	}
98	
99	export interface PurchaseResult {
100	  readonly ok: boolean;
101	  readonly rejection: LedgerRejection | null;
102	  /** The purchase: the one just made, or the original one for a repeated request. */
103	  readonly purchase: PurchaseRecord | null;
104	  /** The refusal kept for this request: the one just decided, or the original one for a repeated request. */
105	  readonly refusal: RefusalRecord | null;
106	  /** This player already used the request id: the original outcome, and nothing was charged or kept again. */
107	  readonly replayed: boolean;
108	}
109	
110	export interface PurchaseRequest {
111	  /** Unique per player in the match; a retry of the same purchase reuses it. Another player's ids never interfere. */
112	  readonly requestId: string;
113	  readonly playerId: string;
114	  readonly item: ShopItem;
115	  readonly tick: number;
116	}
117	
118	function sameRequest(outcome: PurchaseOutcome, playerId: string, requestId: string): boolean {
119	  return outcome.playerId === playerId && outcome.requestId === requestId;
120	}
121	
122	/** Keeps a refusal, dropping the player's oldest kept refusal when they already have `MAX_RECORDED_REFUSALS`. */
123	function keepRefusal(state: LedgerState, refusal: RefusalRecord): LedgerState {
124	  const kept = state.requests.filter((outcome) => outcome.kind === "refusal" && outcome.playerId === refusal.playerId);
125	  const evicted = kept.length >= MAX_RECORDED_REFUSALS ? kept[0] : undefined;
126	  const requests = state.requests.filter((outcome) => outcome !== evicted);
127	  return { ...atTick(state, refusal.tick), requests: [...requests, refusal] };
128	}
129	
130	/**
131	 * A dockside purchase (§11), at the rules' price. The gold is spent: it leaves the buyer's balance for `goldSpent`.
132	 * A tonic goes into the buyer's carried count; a rumor is delivered by the caller after an applied purchase.
133	 *
134	 * Request ids are per player. A (player, request id) already decided returns the original outcome, purchase or
135	 * refusal, with `replayed` and the same state, whatever the tick, so a retry never pays twice and never buys what was
136	 * refused; reused for another item, it is a `duplicate`. A decision to refuse (gold short, the carry limit, a duel,
137	 * a disconnect) is kept, charging nothing, up to `MAX_RECORDED_REFUSALS` per player (oldest dropped first; a
138	 * dropped id is decided afresh). Malformed, stale, unknown-player and left-player requests change nothing.
139	 */
140	export function purchase(state: LedgerState, request: PurchaseRequest): LedgerStep<PurchaseResult> {
141	  const { requestId, playerId, item, tick } = request;
142	  const rejected = (rejection: LedgerRejection): LedgerStep<PurchaseResult> => ({
143	    state,
144	    result: { ok: false, rejection, purchase: null, refusal: null, replayed: false },
145	  });
146	  if (!isKey(requestId) || !isPlayerId(playerId) || !SHOP_ITEMS.includes(item)) return rejected("invalid-request");
147	  const original = state.requests.find((outcome) => sameRequest(outcome, playerId, requestId));
148	  if (original) {
149	    if (original.item !== item) return rejected("duplicate");
150	    const result: PurchaseResult =
151	      original.kind === "purchase"
152	        ? { ok: true, rejection: null, purchase: original, refusal: null, replayed: true }
153	        : { ok: false, rejection: original.rejection, purchase: null, refusal: original, replayed: true };
154	    return { state, result };
155	  }
156	  const bad = tickRejection(state, tick) ?? playerRejection(state, playerId);
157	  if (bad) return rejected(bad);
158	  const buyer = findPlayer(state, playerId)!;
159	  const price = itemPrice(state.rules, item);
160	  const decided: RecordedRefusal | null =
161	    buyer.status === "disconnected"
162	      ? "player-disconnected"
163	      : activeDuelOf(state, playerId)
164	        ? "player-in-duel"
165	        : item === "tonic" && buyer.tonics >= state.rules.tonicCarryLimit
166	          ? "tonic-limit"
167	          : buyer.gold < price
168	            ? "insufficient-gold"
169	            : null;
170	  if (decided !== null) {
171	    const refusal: RefusalRecord = { kind: "refusal", requestId, playerId, item, tick, rejection: decided };
172	    return { state: keepRefusal(state, refusal), result: { ok: false, rejection: decided, purchase: null, refusal, replayed: false } };
173	  }
174	  const record: PurchaseRecord = {
175	    kind: "purchase",
176	    requestId,
177	    playerId,
178	    item,
179	    price,
180	    tick,
181	    goldAfter: buyer.gold - price,
182	    tonicsAfter: item === "tonic" ? buyer.tonics + 1 : buyer.tonics,
183	  };
184	  const next = updatePlayer(
185	    { ...atTick(state, tick), requests: [...state.requests, record], goldSpent: state.goldSpent + price },
186	    playerId,
187	    (player) => ({ ...player, gold: record.goldAfter, tonics: record.tonicsAfter }),
188	  );
189	  return { state: next, result: { ok: true, rejection: null, purchase: record, refusal: null, replayed: false } };
190	}
191	
192	export interface TonicResult {
193	  readonly ok: boolean;
194	  readonly rejection: LedgerRejection | null;
195	  /** The player as they now stand, or null for an unknown player. */
196	  readonly player: LedgerPlayer | null;
197	}
198	
199	export interface UseTonicRequest {
200	  readonly playerId: string;
201	  readonly tick: number;
202	  /** The player is sailing, not on an island or in a dock interaction. */
203	  readonly atSea: boolean;
204	  /** The player is being grappled right now (the world knows; the ledger does not). */
205	  readonly grappled: boolean;
206	}
207	
208	/** Whether a player's sail tonic is active at `tick`; the sailing code applies its speed bonus (§11). */
209	export function activeTonic(state: LedgerState, playerId: string, tick: number): boolean {
210	  const effect = findPlayer(state, playerId)?.tonicEffect ?? null;
211	  return effect !== null && effect.startTick <= tick && tick < effect.endTick;
212	}
213	
214	/**
215	 * Activates one carried tonic at `tick` for `tonicTicks` (§11): active on ticks `tick` to `tick + tonicTicks - 1`.
216	 * Refused while one is active (they never stack), in a duel, while disconnected, grappled or not at sea.
217	 */
218	export function useTonic(state: LedgerState, request: UseTonicRequest): LedgerStep<TonicResult> {
219	  const { playerId, tick, atSea, grappled } = request;
220	  const rejected = (rejection: LedgerRejection): LedgerStep<TonicResult> => ({
221	    state,
222	    result: { ok: false, rejection, player: playerOf(state, playerId) },
223	  });
224	  const bad = tickRejection(state, tick);
225	  if (bad) return rejected(bad);
226	  if (typeof atSea !== "boolean" || typeof grappled !== "boolean") return rejected("invalid-request");
227	  const refusal = playerRejection(state, playerId);
228	  if (refusal) return rejected(refusal);
229	  const player = findPlayer(state, playerId)!;
230	  if (player.status === "disconnected") return rejected("player-disconnected");
231	  if (activeDuelOf(state, playerId)) return rejected("player-in-duel");
232	  if (grappled) return rejected("grappled");
233	  if (!atSea) return rejected("not-at-sea");
234	  if (player.tonics === 0) return rejected("no-tonic");
235	  if (activeTonic(state, playerId, tick)) return rejected("tonic-active");
236	  const next = updatePlayer(atTick(state, tick), playerId, (current) => ({
237	    ...current,
238	    tonics: current.tonics - 1,
239	    tonicEffect: { startTick: tick, endTick: tick + state.rules.tonicTicks },
240	  }));
241	  return { state: next, result: { ok: true, rejection: null, player: findPlayer(next, playerId) ?? null } };
242	}
