1	import { compassHeading, isNavigable } from "@pirate-sea-race/content";
2	import type { SimulationConfig } from "./config.js";
3	import { normalizeHeading } from "./heading.js";
4	import { nextInt } from "./random.js";
5	
6	/** 60 fixed steps per second: the one match clock (§15). */
7	export const STEPS_PER_SECOND = 60;
8	/** World logic runs on every third step, 20 times a second (§15). */
9	export const WORLD_STEP_INTERVAL = 3;
10	
11	/** `dock` of a ship at sea. */
12	export const NOT_DOCKED = -1;
13	
14	/** A ship on the sea. Every number is an integer; positions are in sub-units. */
15	export interface ShipState {
16	  readonly id: string;
17	  readonly slot: number;
18	  readonly x: number;
19	  readonly y: number;
20	  /** One of HEADING_COUNT directions: 0 is east, counting clockwise because y grows down. */
21	  readonly heading: number;
22	  /** Sub-units per world step along the heading; negative when reversing. */
23	  readonly speed: number;
24	  /** The id of the dock the ship is moored at, or NOT_DOCKED. */
25	  readonly dock: number;
26	  /**
27	   * The throttle direction (-1, 0 or 1) held when the ship moored. It does not cast off until it is released, so a
28	   * player who drives into a dock with ahead held stays moored. Always 0 at sea.
29	   */
30	  readonly mooredThrottle: number;
31	}
32	
33	/** The complete match state: plain, serializable data that `hashState` covers entirely. */
34	export interface MatchState {
35	  /** Steps completed on the 60 Hz match clock. */
36	  readonly frame: number;
37	  /** World steps completed (every third frame). */
38	  readonly worldTick: number;
39	  /** The seeded generator's state. */
40	  readonly rng: number;
41	  /** In join order. */
42	  readonly ships: readonly ShipState[];
43	}
44	
45	export function createMatchState(seed: number): MatchState {
46	  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
47	  return { frame: 0, worldTick: 0, rng: seed >>> 0, ships: [] };
48	}
49	
50	/** The centre of a tile, in sub-units. */
51	export function tileCentre(config: SimulationConfig, tileX: number, tileY: number): { x: number; y: number } {
52	  const size = config.map.subUnitsPerTile;
53	  const half = Math.floor(size / 2);
54	  return { x: tileX * size + half, y: tileY * size + half };
55	}
56	
57	/** Adds a ship at rest on a random free spawn slot, facing the slot's heading. Two ships never share a slot. */
58	export function addShip(config: SimulationConfig, state: MatchState, id: string): MatchState {
59	  if (state.ships.some((ship) => ship.id === id)) throw new Error(`ship ${id} already exists`);
60	  const taken = new Set(state.ships.map((ship) => ship.slot));
61	  const free = config.spawnSlots.map((_, index) => index).filter((index) => !taken.has(index));
62	  if (free.length === 0) throw new Error("no free spawn slot");
63	  const drawn = nextInt(state.rng, free.length);
64	  const slot = free[drawn.value]!;
65	  const spawn = config.spawnSlots[slot]!;
66	  const ship: ShipState = {
67	    id,
68	    slot,
69	    ...tileCentre(config, spawn.tileX, spawn.tileY),
70	    heading: compassHeading(spawn.facing),
71	    speed: 0,
72	    dock: NOT_DOCKED,
73	    mooredThrottle: 0,
74	  };
75	  return { ...state, rng: drawn.state, ships: [...state.ships, ship] };
76	}
77	
78	export function removeShip(state: MatchState, id: string): MatchState {
79	  return { ...state, ships: state.ships.filter((ship) => ship.id !== id) };
80	}
81	
82	export interface Placement {
83	  readonly tileX: number;
84	  readonly tileY: number;
85	  readonly heading: number;
86	}
87	
88	/**
89	 * Moves a ship to rest at the centre of a navigable tile. Only the server's test-placement setting calls this (tests
90	 * put ships where a scenario needs them); matches never do.
91	 */
92	export function placeShip(config: SimulationConfig, state: MatchState, id: string, placement: Placement): MatchState {
93	  const { tileX, tileY, heading } = placement;
94	  if (![tileX, tileY, heading].every(Number.isInteger)) throw new RangeError("a placement needs integer tiles and heading");
95	  if (!isNavigable(config.map, tileX, tileY)) throw new RangeError(`tile ${tileX},${tileY} is not navigable`);
96	  if (!state.ships.some((ship) => ship.id === id)) throw new Error(`no ship ${id}`);
97	  const placed = { ...tileCentre(config, tileX, tileY), heading: normalizeHeading(heading), speed: 0, dock: NOT_DOCKED, mooredThrottle: 0 };
98	  return { ...state, ships: state.ships.map((ship) => (ship.id === id ? { ...ship, ...placed } : ship)) };
99	}
100	
101	/** A position as the tile it lies on plus the sub-unit offset inside that tile. */
102	export function toTilePosition(config: SimulationConfig, x: number, y: number) {
103	  const size = config.map.subUnitsPerTile;
104	  return {
105	    tileX: Math.floor(x / size),
106	    tileY: Math.floor(y / size),
107	    offsetX: x % size,
108	    offsetY: y % size,
109	  };
110	}
