1	import { MAX_INPUT_LEAD_FRAMES, MessageType, type InputMessage } from "@pirate-sea-race/protocol";
2	import { STEPS_PER_SECOND } from "@pirate-sea-race/simulation";
3	import { NEUTRAL_HELM, type Helm } from "./keyboard.js";
4	
5	/** Resend a held input this often, well inside the server's 250 ms hold window. */
6	const REFRESH_MS = 100;
7	/** Never tag an input further ahead than half the server's future-frame window. */
8	const MAX_ESTIMATE_LEAD = Math.floor(MAX_INPUT_LEAD_FRAMES / 2);
9	
10	/** The client's estimate of the server's current frame: the last patched frame plus the time since it arrived. */
11	export function estimateServerFrame(patchedFrame: number, patchedAt: number, now: number): number {
12	  const elapsed = Math.max(0, Math.floor(((now - patchedAt) * STEPS_PER_SECOND) / 1000));
13	  return patchedFrame + Math.min(elapsed, MAX_ESTIMATE_LEAD);
14	}
15	
16	export interface InputChannel {
17	  send(type: string, message: InputMessage): void;
18	}
19	
20	/** Sends the player's intent: on every change, and repeated while a key is held. */
21	export class InputSender {
22	  private seq = 0;
23	  private last: Helm = NEUTRAL_HELM;
24	  private lastSentAt = Number.NEGATIVE_INFINITY;
25	  private patchedFrame = 0;
26	  private patchedAt = 0;
27	
28	  constructor(private readonly channel: InputChannel) {}
29	
30	  observeFrame(frame: number, now: number): void {
31	    if (frame !== this.patchedFrame) {
32	      this.patchedFrame = frame;
33	      this.patchedAt = now;
34	    }
35	  }
36	
37	  update(helm: Helm, now: number): void {
38	    const changed = helm.moveX !== this.last.moveX || helm.moveY !== this.last.moveY || helm.buttons !== this.last.buttons;
39	    const held = helm.moveX !== 0 || helm.moveY !== 0 || helm.buttons !== 0;
40	    if (!changed && !(held && now - this.lastSentAt >= REFRESH_MS)) return;
41	    this.channel.send(MessageType.Input, {
42	      seq: ++this.seq,
43	      frame: estimateServerFrame(this.patchedFrame, this.patchedAt, now),
44	      buttons: helm.buttons,
45	      moveX: helm.moveX,
46	      moveY: helm.moveY,
47	    });
48	    this.last = helm;
49	    this.lastSentAt = now;
50	  }
51	}
