/** Validates an untrusted purchase request: its size, then its schema. */
export function validateBuyRumorMessage(message: unknown): BuyRumorMessage | undefined {
  const size = encodedSize(message);
  if (size === undefined || size > MAX_BUY_RUMOR_BYTES) return undefined;
  const parsed = buyRumorMessageSchema.safeParse(message);
  return parsed.success ? parsed.data : undefined;
}

/**
 * Why a purchase was refused, charging nothing: `busy` (two requests already wait), `not-in-play`, `not-at-dock` (the
 * ship was not moored at a dock on the tick it was processed), the ledger's `player-in-duel`, `player-disconnected`
 * and `insufficient-gold`, and the intel module's `covered` (free coverage, or this step gives the type anyway),
 * `capped`, `none` (nothing to sell) and `duplicate`.
 */
export const RUMOR_REFUSAL_NAMES = [
  "busy",
  "not-in-play",
  "not-at-dock",
  "player-in-duel",
  "player-disconnected",
  "insufficient-gold",
  "covered",
  "capped",
  "none",
  "duplicate",
] as const;
export type RumorRefusalName = (typeof RUMOR_REFUSAL_NAMES)[number];

/**
 * The answer to one purchase request: `bought` with the gold it cost (the lead itself arrives as a `journal` message,
 * again on a replay), or `refused` with its reason and nothing charged. `replayed` answers an id already decided.
 */
export const rumorResultMessageSchema = z.discriminatedUnion("outcome", [
  z.strictObject({ requestId: z.string().min(1).max(32), type: typeSchema, outcome: z.literal("bought"), price: z.int().min(0), replayed: z.boolean() }),
  z.strictObject({ requestId: z.string().min(1).max(32), type: typeSchema, outcome: z.literal("refused"), reason: z.enum(RUMOR_REFUSAL_NAMES), replayed: z.boolean() }),
]);
export type RumorResultMessage = z.infer<typeof rumorResultMessageSchema>;

export function parseRumorResultMessage(message: unknown): RumorResultMessage | undefined {

import { z } from "zod";

export const MessageType = {
  /** Client → server: the player's held intent. */
  Input: "input",
} as const;

/** Largest input message accepted, measured as its JSON encoding. A valid one is well under 100 bytes. */
export const MAX_INPUT_MESSAGE_BYTES = 128;
/** How far ahead of the server's current frame an input's frame tag may be (§15: reject future-frame spam). */
export const MAX_INPUT_LEAD_FRAMES = 30;
/** Input messages a client may send per second of match time before the server drops the rest. */
export const MAX_INPUT_MESSAGES_PER_SECOND = 60;
/** The server repeats a held input for at most this many frames (250 ms) without a fresh one, then goes neutral. */
export const INPUT_HOLD_FRAMES = 15;

export const MAX_SEQUENCE = 2 ** 31 - 1;

/**
 * Button bits (§8). Interact (E) docks a ship near a dock; grapple (J, protocol v5) asks the encounter rules to start a
 * grapple (§6), whose target the server chooses; fruit (F held, protocol v9) eats the fruit at the pedestal where the
 * ship is moored (§9). The other bits are reserved for world actions.
 */
export const Buttons = {
  Interact: 1 << 0,
  Grapple: 1 << 1,
  Fruit: 1 << 2,
} as const;

/**
 * One frame-tagged input (§16): a strictly increasing sequence number, the client's estimate of the server frame,
 * a button bit field and movement axes bounded to [-1, 1]. Axes outside the range are rejected, not clamped.
 *
 * At sea (protocol v3) the axes steer a ship: `moveX` turns (positive clockwise, to starboard) and `moveY` is the
 * throttle, negative ahead (up on a keyboard) and positive to brake, then reverse slowly from a stop.
 */
export const inputMessageSchema = z.strictObject({
  seq: z.int().min(1).max(MAX_SEQUENCE),
  frame: z.int().min(0).max(MAX_SEQUENCE),
  buttons: z.int().min(0).max(0xffff),

